mapper.insert:
INSERT INTO TIA_B_LEASE_TRAN (COMPANY_CODE, SEQ, TRAN_SEQ, CRTUSERNO, CRTDATE, TRAN_DT, VAT_CODE, DPST_AMT, DPST_AMT_RTN, MON_RENT, VAT_AMT, REMARK, BLTR_COMPANY_CODE, BLTR_SEQ, SLIP_ID, SLIP_IDSEQ, CONT_SEQ) SELECT A.COMPANY_CODE, A.SEQ, SIA_B_LEASE_TRAN_SEQ.NEXTVAL as TRAN_SEQ, #{userNo,jdbcType=NUMERIC} as CRTUSERNO, SYSDATE as CRTDATE, TO_DATE(A.TRAN_DT, 'YYYY-MM-DD') as TRAN_DT, NULL as VAT_CODE, A.DPST_AMT, A.DPST_AMT_RTN, A.MON_RENT, 0 as VAT_AMT, A.REMARK, NULL as BLTR_COMPANY_CODE, NULL as BLTR_SEQ, NULL as SLIP_ID, NULL as SLIP_IDSEQ, A.CONT_SEQ FROM ( SELECT A.COMPANY_CODE, A.SEQ, B.CONT_SEQ, SF_DATETOSTRING(A.CONT_DT) AS TRAN_DT, B.DPST_AMT, 0 as MON_RENT, 0 as DPST_AMT_RTN, '최초계약, 보증금' as REMARK FROM TIA_B_LEASE A, TIA_B_LEASE_CONT B WHERE A.SEQ = B.SEQ AND A.SEQ = #{seq} AND B.CONT_SEQ = #{contSeq}
UNION ALL
SELECT A.COMPANY_CODE, A.SEQ, B.CONT_SEQ, SF_DATETOSTRING(B.CHG_DT) AS TRAN_DT, 0 as DPST_AMT, 0 as MON_RENT, B.DPST_AMT as DPST_AMT_RTN, '계약종료, 보증금 상환' as REMARK FROM TIA_B_LEASE A, TIA_B_LEASE_CONT B WHERE A.SEQ = B.SEQ AND A.SEQ = #{seq} AND B.CONT_SEQ = #{contSeq} ) A

INSERT INTO TIA_B_LEASE_INTR (COMPANY_CODE, SEQ, INTR_DT_F, CRTUSERNO, CRTDATE, INTR_DT_T, DPST_AMT, INTR_RATE, INTR_AMT, CONT_SEQ) SELECT COMPANY_CODE, SEQ, V_ST as INTR_DT_F, #{userNo,jdbcType=NUMERIC} as CRTUSERNO, SYSDATE as CRTDATE, V_FN as INTR_DT_T, DPST_AMT, DPST_INTR_RATE as INTR_RATE, ROUND(((V_DAY/365)*(DPST_INTR_RATE/100))*DPST_AMT) as INTR_AMT, CONT_SEQ FROM ( SELECT LEV, LAST_LEV, CONT_DT, CHG_DT, (CASE WHEN LEV=1 THEN CONT_DT ELSE V_ST END) as V_ST, (CASE WHEN LEV=LAST_LEV THEN CHG_DT ELSE V_FN END) as V_FN, ((CASE WHEN LEV=LAST_LEV THEN CHG_DT ELSE V_FN END)-(CASE WHEN LEV=1 THEN CONT_DT ELSE V_ST END))+1 as V_DAY, DPST_INTR_RATE, DPST_AMT, SEQ, CONT_SEQ, COMPANY_CODE FROM ( SELECT LEVEL as LEV, CONT_DT, CHG_DT, TO_DATE(TO_CHAR(ADD_MONTHS(TO_DATE(ST_DT,'YYYYMM'), LEVEL-1),'YYYY-MM')||'-01', 'YYYY-MM-DD') as V_ST, LAST_DAY(TO_DATE(TO_CHAR(ADD_MONTHS(TO_DATE(ST_DT,'YYYYMM'), LEVEL-1),'YYYY-MM')||'-01', 'YYYY-MM-DD')) as V_FN, DPST_INTR_RATE, DPST_AMT, COUNT(*)OVER() as LAST_LEV, SEQ, CONT_SEQ, COMPANY_CODE FROM ( SELECT A.COMPANY_CODE, A.DPST_INTR_RATE, B.DPST_AMT, A.CONT_DT, B.CHG_DT, TO_CHAR(A.CONT_DT,'YYYYMM') as ST_DT, TO_CHAR(B.CHG_DT,'YYYYMM') as FN_DT, A.SEQ, B.CONT_SEQ FROM TIA_B_LEASE A, TIA_B_LEASE_CONT B WHERE A.SEQ = B.SEQ AND A.SEQ = #{seq} AND B.CONT_SEQ = #{contSeq} ) A
CONNECT BY LEVEL <= MONTHS_BETWEEN(TO_DATE(FN_DT,'YYYYMM'),TO_DATE(ST_DT,'YYYYMM'))+1
) Z ) X
